sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Control regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Small Cell Lung' AND TRIM(COALESCE("Control arm", '')) = 'Chemo' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Control regimen", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Small Cell Lung' AND TRIM(COALESCE("Control arm", '')) = 'Chemo' AND TRIM(COALESCE("Name of ICI", '')) = 'Ipilimumab' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_specific_regimens(source_value) AS "specific_regimens"
FROM base;
